// settings-panel/gui-dna-core.js — the genes a renderer builds (devdoc/gui-dna.md §5), as pure
// functions returning markup, so a gene's markup lives in one place. No host imports: unit-tested directly
// (tests/gui-dna-core.test.js).
//
// TEXT. Every string is escaped here, and its parameter's name says which kind it is:
//   • `text`, `title` and `placeholder` are fixed words. Pass the English source, which is also the translation key;
//     it comes out keyed (data-i18n, data-i18n-title, data-i18n-placeholder), so the panel's locale pass translates a
//     built row like static markup.
//   • `name` is data — a character, an outfit, a call — shown as written and never keyed.
// The G1 guard reads every `text:`, `title:` and `placeholder:` literal in a file that builds with these, and checks
// it against zh-cn.
//
// HOOKS. `data` (and `nameData` on a record card) becomes data-* attributes: a renderer finds its elements by those,
// never by a gene's class.
//
// THE CARD GATE. What a control needs is declared where it sits: data-vfx-needs="card" (a card is open) or "chat"
// (that card's chat has started). The shell (settings-panel.js paintCardScope) makes every region whose need is unmet
// inert and shows its page's notice (data-vfx-notice-for). `isNeedUnmet` below is the decision; a button a renderer
// builds outside a declared region declares its own (`needs`).

import { escapeHtmlAttribute as escape } from '../html-escape.js';

/**
 * Whether a region declaring `need` waits now. A chat belongs to a card, so no card leaves both unmet. A need this
 * build does not know always waits: a misspelt declaration greys its region instead of leaving it open.
 */
export function isNeedUnmet(need, { isCardOpen, isChatStarted }) {
    if (need === 'card') return !isCardOpen;
    if (need === 'chat') return !(isCardOpen && isChatStarted);
    return true;
}

/**
 * The theme the panel wears (devdoc/gui-dna.md §3, Themes). Light only when the user picked it: a missing or unknown
 * value is the dark default, the palette on the root class.
 */
export function panelThemeOf(saved) {
    return saved === 'light' ? 'light' : 'dark';
}

function needsAttribute(needs) {
    return needs ? ` data-vfx-needs="${escape(needs)}"` : '';
}

const PILL_STATUSES = ['success', 'warning', 'danger', 'neutral', 'accent'];
const BUTTON_KIND_CLASSES = { primary: ' vfx-btn-primary', danger: ' vfx-btn-danger', quiet: ' vfx-btn-quiet', secondary: '' };
const HELP_TOGGLE = '<button type="button" class="vfx-help-toggle" aria-expanded="false" data-i18n-title="More about this" title="More about this"><i class="fa-solid fa-circle-question"></i></button>';
const COLLAPSE_TOGGLE = '<button type="button" class="vfx-collapse" aria-expanded="true" data-i18n-title="Show or hide" title="Show or hide"><i class="fa-solid fa-chevron-up"></i></button>';
const HIDDEN = ' style="display:none;"';

// { 'roster-action': 'edit', uid: 7 } → ` data-roster-action="edit" data-uid="7"`; null and undefined values are left out.
function dataAttributes(data = {}) {
    return Object.entries(data)
        .filter(([, value]) => value !== undefined && value !== null)
        .map(([name, value]) => ` data-${name}="${escape(String(value))}"`)
        .join('');
}

function iconTag(icon, extraClass = '') {
    return icon ? `<i class="fa-solid ${escape(icon)}${extraClass}"></i>` : '';
}

function keyedText(text) {
    return `<span data-i18n="${escape(text)}">${escape(text)}</span>`;
}

function titleAttributes(title) {
    return title ? ` data-i18n-title="${escape(title)}" title="${escape(title)}"` : '';
}

function placeholderAttributes(placeholder) {
    return placeholder ? ` data-i18n-placeholder="${escape(placeholder)}" placeholder="${escape(placeholder)}"` : '';
}

// min="0" step="0.1" … for the numeric limits that are set.
function limitAttributes(limits) {
    return Object.entries(limits)
        .filter(([, value]) => value !== undefined && value !== null && value !== '')
        .map(([name, value]) => ` ${name}="${escape(String(value))}"`)
        .join('');
}

// A fixed word (`text`, keyed) or data (`name`, as written).
function label({ text, name }) {
    return text !== undefined ? keyedText(text) : escape(String(name ?? ''));
}

const isShown = (value) => value !== undefined && value !== null && String(value) !== '';

// A LINE, as a list row's sub-line, a result line or a notice: { text } a fixed word, { name } a value, { text, name }
// a keyed lead-in, a colon and the value, or { parts } — fixed words ({ text }), values ({ name }) and code chips
// ({ code }) in order. '' when it has nothing to show; a lead-in whose value is empty shows nothing.
function lineContent(line) {
    if (!line || typeof line !== 'object') return '';
    if (Array.isArray(line.parts)) return line.parts.map(partContent).join('');
    if ('name' in line) {
        if (!isShown(line.name)) return '';
        return `${line.text !== undefined ? `${keyedText(line.text)}: ` : ''}${escape(String(line.name))}`;
    }
    return line.text ? keyedText(line.text) : '';
}

function partContent(part) {
    if (!part) return '';
    if (part.text) return keyedText(part.text);
    if (isShown(part.code)) return codeChip({ name: part.code });
    return isShown(part.name) ? escape(String(part.name)) : '';
}

/**
 * Icon button: 32px square, its translated title is its accessible name. `isPressed` (true/false) makes it an icon
 * toggle: aria-pressed, and `.is-on` while pressed. `isDanger` for a destructive row action.
 */
export function iconButton({ icon, title, isDanger = false, isPressed = null, isDisabled = false, data } = {}) {
    const classes = `vfx-btn vfx-btn-icon${isDanger ? ' vfx-btn-danger' : ''}${isPressed === true ? ' is-on' : ''}`;
    const pressed = typeof isPressed === 'boolean' ? ` aria-pressed="${isPressed}"` : '';
    return `<button type="button" class="${classes}"${titleAttributes(title)}${pressed}${isDisabled ? ' disabled' : ''}${dataAttributes(data)}>${iconTag(icon)}</button>`;
}

/**
 * Text button; `kind` is primary, secondary (the default), quiet or danger. `needs` ('card' or 'chat') gates a button
 * that acts on the card from a region that does not (the card gate, above).
 */
export function button({ text, icon = '', kind = 'secondary', isDisabled = false, needs = '', data } = {}) {
    const kindClass = BUTTON_KIND_CLASSES[kind] ?? '';
    return `<button type="button" class="vfx-btn${kindClass}"${isDisabled ? ' disabled' : ''}${needsAttribute(needs)}${dataAttributes(data)}>${iconTag(icon)}${keyedText(text)}</button>`;
}

/**
 * Status pill: a fixed word (`text`) or a value (`name`); `status` is success, warning, danger, neutral or accent.
 * `isHidden` renders it hidden, for a pill its renderer shows when the status arises.
 */
export function statusPill({ text, name, status = 'neutral', icon = '', isHidden = false, data } = {}) {
    const statusClass = PILL_STATUSES.includes(status) ? status : 'neutral';
    return `<span class="vfx-pill is-${statusClass}"${isHidden ? HIDDEN : ''}${dataAttributes(data)}>${iconTag(icon)}${label({ text, name })}</span>`;
}

/**
 * List row: leading icon, a name (data) or a fixed word (`text`), sub-lines, pills, trailing actions. `sub` is one line
 * or a list of them (see LINE above: "Also known as: …"); a line with nothing to show is left out. `pills` and
 * `actions` are markup from the builders above. The name and its pills share `.vfx-row-info`, so the pills can wrap
 * under the name while the actions stay beside it.
 */
export function listRow({ icon, text, name, sub = null, pills = [], actions = [], data } = {}) {
    const subLines = (Array.isArray(sub) ? sub : [sub]).map(lineContent).filter(Boolean)
        .map((content) => `<div class="vfx-row-sub">${content}</div>`).join('');
    return `<div class="vfx-row"${dataAttributes(data)}>${iconTag(icon, ' vfx-row-icon')}`
        + `<div class="vfx-row-info"><div class="vfx-row-main"><div class="vfx-row-name">${label({ text, name })}</div>${subLines}</div>`
        + `<div class="vfx-row-pills">${pills.join('')}</div></div>`
        + `<div class="vfx-row-actions">${actions.join('')}</div></div>`;
}

/**
 * Record card: a header (an enable switch, icon, a fixed word or a name, pills, trailing actions, and the collapse
 * chevron when `isCollapsible`) over a body of builder markup. `nameData` hooks the name, for a renderer that rewrites
 * it while the record's name field is typed in.
 */
export function recordCard({ icon = '', text, name, nameData, toggle = '', pills = [], actions = [], body = '', data, isCollapsible = false } = {}) {
    return `<div class="vfx-record"${dataAttributes(data)}>`
        + `<div class="vfx-record-header">${toggle}${iconTag(icon)}<span class="vfx-record-name"${dataAttributes(nameData)}>${label({ text, name })}</span>`
        + `${pills.join('')}${actions.join('')}${isCollapsible ? COLLAPSE_TOGGLE : ''}</div>`
        + `<div class="vfx-record-body">${body}</div></div>`;
}

/** Grid of fields: two columns (one on phone); `isPair` stays two columns on phone; `isSpan` takes a parent grid's whole row. */
export function grid(parts = [], { isPair = false, isSpan = false } = {}) {
    return `<div class="${isPair ? 'vfx-grid-pair' : 'vfx-grid'}${isSpan ? ' vfx-span' : ''}">${parts.join('')}</div>`;
}

/** Stack: fields one under another at any width — a dialog's form. */
export function stack(parts = []) {
    return `<div class="vfx-stack">${parts.join('')}</div>`;
}

/** Field: a column of builder markup (label, control, hint, detail); `isSpan` takes the grid's whole row. */
export function field(parts = [], { isSpan = false } = {}) {
    return `<div class="vfx-field${isSpan ? ' vfx-span' : ''}">${parts.join('')}</div>`;
}

/** A field's label row: the label (for the control `forId`, else a plain caption) and its (?) when `hasHelp`. */
export function fieldLabel({ text, forId = '', hasHelp = false } = {}) {
    const caption = forId
        ? `<label for="${escape(forId)}" data-i18n="${escape(text)}">${escape(text)}</label>`
        : keyedText(text);
    return `<div class="vfx-field-label">${caption}${hasHelp ? HELP_TOGGLE : ''}</div>`;
}

/** Control row: controls and buttons on one line; a select or input in it takes the free width. */
export function controlRow(parts = []) {
    return `<div class="vfx-control-row">${parts.join('')}</div>`;
}

/**
 * Hint: one muted line under a control. `chip` (codeChip markup) follows the words: a live value the translated words
 * lead into, kept outside them.
 */
export function hint({ text, chip = '' } = {}) {
    if (!chip) return `<p class="vfx-hint" data-i18n="${escape(text)}">${escape(text)}</p>`;
    return `<p class="vfx-hint">${keyedText(text)} ${chip}</p>`;
}

/** Detail: the field's longer explanation, shown while its (?) is open. */
export function detail({ text } = {}) {
    return `<p class="vfx-detail" data-i18n="${escape(text)}">${escape(text)}</p>`;
}

/** Code chip: a tag, path or pattern shown as written. */
export function codeChip({ name, data } = {}) {
    return `<code class="vfx-code"${dataAttributes(data)}>${escape(String(name ?? ''))}</code>`;
}

/**
 * Input holding `value`: `type` text (the default) or number with its `min`, `max` and `step`. `title` is its
 * accessible name where no label names it; `isCode` sets it in the monospace font (patterns); `isDisabled` shows a
 * value that cannot change here.
 */
export function input({ id, type = 'text', value = '', placeholder, title, isCode = false, isDisabled = false, min, max, step, data } = {}) {
    const inputType = type === 'number' ? 'number' : 'text';
    return `<input type="${inputType}" id="${escape(id)}" class="vfx-input${isCode ? ' is-code' : ''}" value="${escape(String(value ?? ''))}"`
        + `${limitAttributes({ min, max, step })}${placeholderAttributes(placeholder)}${titleAttributes(title)}${isDisabled ? ' disabled' : ''}${dataAttributes(data)}>`;
}

/** Textarea holding `value`; `title` is its accessible name; `isCode` sets it in the monospace font. */
export function textarea({ id, value = '', rows = 4, isCode = false, title } = {}) {
    return `<textarea id="${escape(id)}" class="vfx-textarea${isCode ? ' is-code' : ''}" rows="${Number(rows) || 4}"${titleAttributes(title)}>${escape(String(value))}</textarea>`;
}

/** Select of `options` (selectOption markup); `title` is its accessible name; `isMissing` marks a required pick not made. */
export function select({ id, title, options = [], isMissing = false, data } = {}) {
    return `<select id="${escape(id)}" class="vfx-select${isMissing ? ' is-missing' : ''}"${titleAttributes(title)}${dataAttributes(data)}>${options.join('')}</select>`;
}

/** One option: a fixed word (`text`, keyed on the option itself — an option holds text only) or a `name`. */
export function selectOption({ value, text, name, isSelected = false } = {}) {
    const keyed = text !== undefined ? ` data-i18n="${escape(text)}"` : '';
    return `<option value="${escape(String(value ?? ''))}"${keyed}${isSelected ? ' selected' : ''}>${escape(String(text ?? name ?? ''))}</option>`;
}

/** A bare switch, for a record header; `title` is its accessible name. */
export function switchInput({ title, isChecked = false, data } = {}) {
    return `<input type="checkbox" role="switch" class="vfx-switch"${titleAttributes(title)}${isChecked ? ' checked' : ''}${dataAttributes(data)}>`;
}

/** Check list: a plain checkbox for each member of a set — items are { name, isChecked, data }. */
export function checkList({ items = [] } = {}) {
    const checks = items.map(({ name, isChecked = false, data }) => '<label class="vfx-check-item">'
        + `<input type="checkbox" class="vfx-check"${isChecked ? ' checked' : ''}${dataAttributes(data)}><span>${escape(String(name ?? ''))}</span></label>`);
    return `<div class="vfx-check-list">${checks.join('')}</div>`;
}

/** Empty state: a muted icon and one line. */
export function emptyState({ icon, text } = {}) {
    return `<div class="vfx-empty">${iconTag(icon)}${keyedText(text)}</div>`;
}

const NOTICE_ICONS = { info: 'fa-circle-info', warning: 'fa-triangle-exclamation', danger: 'fa-circle-exclamation' };

/**
 * Notice: a full-width banner for a condition. `status` is info, warning or danger; its sentence is a LINE; `action` is
 * a button (builder markup) after it, for the one fix the notice offers.
 */
export function notice({ status = 'info', icon = '', action = '', ...line } = {}) {
    const statusClass = NOTICE_ICONS[status] ? status : 'info';
    return `<div class="vfx-notice is-${statusClass}">${iconTag(icon || NOTICE_ICONS[statusClass])}<p class="vfx-notice-text">${lineContent(line)}</p>${action}</div>`;
}

/** Group title: a sub-heading inside a card, over the list it heads; its words are a LINE. */
export function groupTitle({ icon = '', ...line } = {}) {
    return `<div class="vfx-group-title">${iconTag(icon)}<span>${lineContent(line)}</span></div>`;
}

const RESULT_ICONS = { success: 'fa-circle-check', warning: 'fa-triangle-exclamation', danger: 'fa-circle-xmark' };

/**
 * Result list: the outcome of a validation, import or generation. `heading` and each of `lines` are LINEs; a line's
 * `status` (success, warning, danger) colours it and picks its icon, and `icon` gives a plain line one. A line with
 * nothing to show is left out.
 */
export function resultList({ heading = null, lines = [] } = {}) {
    const headingContent = lineContent(heading);
    const items = lines.map((line) => {
        const content = lineContent(line);
        if (!content) return '';
        const status = RESULT_ICONS[line.status] ? line.status : '';
        return `<li class="vfx-result-line${status ? ` is-${status}` : ''}">${iconTag(line.icon || RESULT_ICONS[status] || '')}<span>${content}</span></li>`;
    });
    return `<ul class="vfx-result">${headingContent ? `<li class="vfx-result-heading">${headingContent}</li>` : ''}${items.join('')}</ul>`;
}

/** Pager: previous and next (disabled at the ends) around "page / pages". `page` counts from 0. */
export function pager({ page, pageCount, previousData, nextData } = {}) {
    return '<div class="vfx-pager">'
        + iconButton({ icon: 'fa-chevron-left', title: 'Previous page', isDisabled: page <= 0, data: previousData })
        + `<span>${Number(page) + 1} / ${Number(pageCount)}</span>`
        + iconButton({ icon: 'fa-chevron-right', title: 'Next page', isDisabled: page >= pageCount - 1, data: nextData })
        + '</div>';
}
